                foreach (var paragraph in body1.Elements<Paragraph>())
                {
                    if (pageCount < 2)
                    {
                        body2.Append(paragraph.CloneNode(true));
                        pageCount++;
                    }
                    else
                    {
                        break;
                    }
                }

                // Copy the header and footer from the first document
                HeaderPart headerPart1 = mainPart1.HeaderParts.FirstOrDefault();
                FooterPart footerPart1 = mainPart1.FooterParts.FirstOrDefault();

                if (headerPart1 != null)
                {
